// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {W_WALLET, Log} from "../src/W_WALLET.sol";

contract InvMutTest is Test {
    W_WALLET c;
    Log logFile;

    function setUp() public {
        logFile = new Log();
        c = new W_WALLET(address(logFile));
    }

    function testFuzz_property(uint256 amount, uint256 unlockTime, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        amount = bound(amount, 1, 100 ether);
        uint256 maxTime = block.timestamp > type(uint256).max - 1e6 ? block.timestamp : block.timestamp + 1e6;
        unlockTime = bound(unlockTime, 0, maxTime);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(unlockTime);

        // General rule: after ANY Put(amount) by actor, the last logged message
        // (History[0] on a fresh log) has Sender == actor and Val == amount.
        address sender0 = address(0);
        uint256 val0 = type(uint256).max;
        try logFile.History(0) returns (address s, string memory, uint256 v, uint256) {
            sender0 = s;
            val0 = v;
        } catch {
            // History empty: no message was ever logged
        }
        assertTrue(sender0 == actor && val0 == amount);
    }
}
